({
  init(msg) {
    if (!this.data) {
      this.data = {};
    }
    if (!Array.isArray(this.data.appointments)) {
      this.data.appointments = [];
    }
    this._checkInvariants();
    return { initialized: true };
  },

  scheduleAppointment(msg) {
    this._ensureData();
    const payload = msg?.payload || {};
    const { id, title, startIso, endIso } = payload;

    this.ensure(typeof id === "string" && id.trim().length > 0, "id must be a non-empty string");
    this.ensure(typeof title === "string" && title.trim().length > 0, "title must be a non-empty string");
    this.ensure(this._isValidIso(startIso), "startIso must be a valid ISO date string");
    this.ensure(this._isValidIso(endIso), "endIso must be a valid ISO date string");

    const startMs = Date.parse(startIso);
    const endMs = Date.parse(endIso);
    this.ensure(startMs < endMs, "startIso must be strictly before endIso");
    this.ensure(!this._findAppointment(id.trim()), `Appointment with id '${id}' already exists`);
    this.ensure(!this._hasOverlap(startMs, endMs), "Appointment time slot conflicts with an existing appointment");

    const appointment = {
      id: id.trim(),
      title: title.trim(),
      startIso: new Date(startMs).toISOString(),
      endIso: new Date(endMs).toISOString()
    };

    this.data.appointments.push(appointment);
    this.data.appointments.sort((a, b) => Date.parse(a.startIso) - Date.parse(b.startIso));

    this._checkInvariants();
    this.changed("appointments", this.data.appointments);

    const created = this._findAppointment(appointment.id);
    this.ensure(created !== undefined, "Scheduled appointment must be recorded in data");

    return created;
  },

  hasConflict(msg) {
    this._ensureData();
    const payload = msg?.payload || {};
    const { startIso, endIso } = payload;

    this.ensure(this._isValidIso(startIso), "startIso must be a valid ISO date string");
    this.ensure(this._isValidIso(endIso), "endIso must be a valid ISO date string");

    const startMs = Date.parse(startIso);
    const endMs = Date.parse(endIso);
    this.ensure(startMs < endMs, "startIso must be strictly before endIso");

    const conflict = this._hasOverlap(startMs, endMs);
    this.ensure(typeof conflict === "boolean", "Conflict result must be a boolean");

    return conflict;
  },

  listBetween(msg) {
    this._ensureData();
    const payload = msg?.payload || {};
    const { fromIso, toIso } = payload;

    this.ensure(this._isValidIso(fromIso), "fromIso must be a valid ISO date string");
    this.ensure(this._isValidIso(toIso), "toIso must be a valid ISO date string");

    const fromMs = Date.parse(fromIso);
    const toMs = Date.parse(toIso);
    this.ensure(fromMs <= toMs, "fromIso must not be after toIso");

    const matches = this.data.appointments.filter((app) => {
      const appStart = Date.parse(app.startIso);
      const appEnd = Date.parse(app.endIso);
      return appStart < toMs && appEnd > fromMs;
    });

    this.ensure(Array.isArray(matches), "Result must be an array of matching appointments");
    return matches;
  },

  _ensureData() {
    if (!this.data) {
      this.data = {};
    }
    if (!Array.isArray(this.data.appointments)) {
      this.data.appointments = [];
    }
  },

  _isValidIso(isoStr) {
    if (typeof isoStr !== "string" || !isoStr.trim()) {
      return false;
    }
    const parsed = Date.parse(isoStr);
    return !Number.isNaN(parsed);
  },

  _findAppointment(id) {
    this._ensureData();
    return this.data.appointments.find((app) => app.id === id);
  },

  _hasOverlap(startMs, endMs, excludeId = null) {
    this._ensureData();
    return this.data.appointments.some((app) => {
      if (excludeId && app.id === excludeId) {
        return false;
      }
      const appStart = Date.parse(app.startIso);
      const appEnd = Date.parse(app.endIso);
      return appStart < endMs && appEnd > startMs;
    });
  },

  _checkInvariants() {
    this.invariant(Boolean(this.data), "Data object must exist");
    this.invariant(Array.isArray(this.data.appointments), "Appointments must be an array");

    const ids = new Set();
    for (let i = 0; i < this.data.appointments.length; i++) {
      const app = this.data.appointments[i];
      this.invariant(typeof app.id === "string" && app.id.length > 0, "Appointment id must be a non-empty string");
      this.invariant(typeof app.title === "string", "Appointment title must be a string");
      this.invariant(!ids.has(app.id), `Duplicate appointment id: ${app.id}`);
      ids.add(app.id);

      const startMs = Date.parse(app.startIso);
      const endMs = Date.parse(app.endIso);
      this.invariant(!Number.isNaN(startMs) && !Number.isNaN(endMs), "Appointment dates must be valid ISO strings");
      this.invariant(startMs < endMs, "Appointment start time must be before end time");

      if (i > 0) {
        const prevApp = this.data.appointments[i - 1];
        const prevEndMs = Date.parse(prevApp.endIso);
        this.invariant(prevEndMs <= startMs, "Appointments must be non-overlapping and sorted chronologically");
      }
    }
  }
})
